// T004 tranche-one acquisition driver for one admitted candidate.
// Generic over (repo, tag, slug); composes the repository's shared acquisition shape:
//   - exact GET, identity encoding, no credentials, no redirects followed
//   - every accepted response ledgered with byte count + sha256
//   - archive fetched twice and required byte-identical
//   - archive reconciled against the git tree by per-blob git object id
// Consent: VL-LEGACY-CORPUS-2026-08-10 (VERSIONLESS_NETWORK_MODE=consented).
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import {
	createWriteStream,
	mkdirSync,
	readFileSync,
	readdirSync,
	rmSync,
	statSync,
	writeFileSync,
	lstatSync,
} from 'node:fs';
import { request } from 'node:https';
import { join, relative } from 'node:path';

const [repo, tag, slug] = process.argv.slice(2);
const consentId = process.env.VERSIONLESS_CONSENT_ID;
if (process.env.VERSIONLESS_NETWORK_MODE !== 'consented' || !consentId)
	throw new Error('acquisition requires VERSIONLESS_NETWORK_MODE=consented and a consent id');

const root = join(new URL('.', import.meta.url).pathname, '../../..');
const evidenceDir = join(root, 'evidence/ingests', slug);
const cacheRoot = join(root, '.versionless/cache', `${slug}-source`);
const archiveDir = join(cacheRoot, 'archive');
const extractDir = join(cacheRoot, 'verify/extracted');
mkdirSync(archiveDir, { recursive: true });

const sha256 = (b) => createHash('sha256').update(b).digest('hex');
const gitBlobId = (b) =>
	createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${b.byteLength}\0`), b])).digest('hex');

const requests = [];
const caps = {
	maximumAcceptedResponses: 7,
	maximumApiResponseBytes: 16777216,
	maximumArchiveBytes: 134217728,
	maximumAggregateWireBytes: 314572800,
	maximumAggregateDecodedBytes: 314572800,
	requiredArchiveStreams: 2,
};
let aggregate = 0;
let redirectsObserved = 0;
let setCookiesUsed = 0;

function get(url, kind, stream) {
	return new Promise((resolve, reject) => {
		const call = request(
			url,
			{
				method: 'GET',
				headers: {
					accept:
						kind === 'json' ? 'application/vnd.github+json' : 'application/octet-stream',
					'accept-encoding': 'identity',
					'user-agent': 'versionless-shared-acquisition',
					'x-versionless-consent-id': consentId,
				},
			},
			(response) => {
				if ((response.statusCode ?? 0) >= 300 && (response.statusCode ?? 0) < 400)
					redirectsObserved += 1;
				if (response.headers['set-cookie']) setCookiesUsed += 1;
				if (response.statusCode !== 200) {
					response.resume();
					reject(new Error(`non-200 ${response.statusCode} for ${url}`));
					return;
				}
				if ((response.headers['content-encoding'] ?? 'identity') !== 'identity') {
					response.resume();
					reject(new Error(`non-identity content-encoding for ${url}`));
					return;
				}
				const chunks = [];
				let bytes = 0;
				response.on('data', (c) => {
					bytes += c.byteLength;
					const cap = kind === 'json' ? caps.maximumApiResponseBytes : caps.maximumArchiveBytes;
					if (bytes > cap || aggregate + bytes > caps.maximumAggregateWireBytes)
						response.destroy(new Error(`cap exceeded for ${url}`));
					else chunks.push(Buffer.from(c));
				});
				response.once('error', reject);
				response.once('end', () => {
					const body = Buffer.concat(chunks, bytes);
					aggregate += bytes;
					const record = { endpoint: url, status: 200, bytes, sha256: sha256(body) };
					if (stream) record.stream = stream;
					requests.push(record);
					resolve(body);
				});
			},
		);
		call.setTimeout(120_000, () => call.destroy(new Error(`timeout for ${url}`)));
		call.once('error', reject);
		call.end();
	});
}

const startedAt = new Date().toISOString();
const api = `https://api.github.com/repos/${repo}`;
const repositoryBody = await get(api, 'json');
const repository = JSON.parse(repositoryBody.toString());
const refJson = JSON.parse((await get(`${api}/git/ref/tags/${tag}`, 'json')).toString());
let tagObject;
let commitSha = refJson.object.sha;
if (refJson.object.type === 'tag') {
	tagObject = JSON.parse((await get(`${api}/git/tags/${refJson.object.sha}`, 'json')).toString());
	commitSha = tagObject.object.sha;
}
const commit = JSON.parse((await get(`${api}/git/commits/${commitSha}`, 'json')).toString());
const tree = JSON.parse(
	(await get(`${api}/git/trees/${commit.tree.sha}?recursive=1`, 'json')).toString(),
);
if (tree.truncated) throw new Error('git tree truncated; refusing partial reconciliation');

const codeload = `https://codeload.github.com/${repo}/tar.gz/${commitSha}`;
const archives = [];
for (const stream of [1, 2]) {
	const body = await get(codeload, 'archive', stream);
	const file = join(archiveDir, `archive-${stream}.tar.gz`);
	writeFileSync(file, body);
	archives.push({ file, sha256: sha256(body), bytes: body.byteLength });
}
const archivesByteIdentical = archives[0].sha256 === archives[1].sha256;
if (!archivesByteIdentical) throw new Error('archive streams differ; refusing to publish source');

rmSync(extractDir, { recursive: true, force: true });
mkdirSync(extractDir, { recursive: true });
execFileSync('tar', ['-xzf', archives[0].file, '-C', extractDir]);
const roots = readdirSync(extractDir);
if (roots.length !== 1) throw new Error(`archive has ${roots.length} roots`);
const singleRoot = roots[0];
const sourceRoot = join(extractDir, singleRoot);

const files = [];
const directories = [];
let specialEntries = 0;
const walk = (dir) => {
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const full = join(dir, entry.name);
		if (entry.isDirectory()) {
			directories.push(full);
			walk(full);
		} else if (entry.isFile()) files.push(full);
		else specialEntries += 1;
	}
};
directories.push(sourceRoot);
walk(sourceRoot);

const treeBlobs = new Map(
	tree.tree.filter((e) => e.type === 'blob' && e.mode !== '120000').map((e) => [e.path, e.sha]),
);
const symlinks = tree.tree.filter((e) => e.mode === '120000').length;
const gitlinks = tree.tree.filter((e) => e.type === 'commit').length;
let mismatchedBlobs = 0;
let extraFiles = 0;
const manifest = [];
const seen = new Set();
for (const file of files) {
	const rel = relative(sourceRoot, file);
	const bytes = readFileSync(file);
	manifest.push(`${rel} ${sha256(bytes)} ${bytes.byteLength}`);
	const expected = treeBlobs.get(rel);
	if (!expected) extraFiles += 1;
	else {
		seen.add(rel);
		if (gitBlobId(bytes) !== expected) mismatchedBlobs += 1;
	}
}
const missingFiles = treeBlobs.size - seen.size;
manifest.sort();
const normalizedManifestSha256 = sha256(Buffer.from(`${manifest.join('\n')}\n`, 'utf8'));
writeFileSync(join(cacheRoot, 'manifest.txt'), `${manifest.join('\n')}\n`);

const archiveMatchesGitTree = mismatchedBlobs === 0 && missingFiles === 0 && extraFiles === 0;
const completedAt = new Date().toISOString();

const attempt = {
	schemaVersion: 'versionless.official-source-attempt.v1',
	candidate: { repository: repo, requestedTag: tag },
	consentId,
	result: 'started',
	network: {
		method: 'GET',
		credentials: 'none',
		requestEncoding: 'identity',
		redirectsAllowed: false,
		retriesAllowed: false,
		alternateHostsAllowed: false,
	},
	allowlist: [
		api,
		`${api}/git/ref/tags/${tag}`,
		`${api}/git/commits/<validated-commit-sha>`,
		`${api}/git/trees/<validated-tree-sha>?recursive=1`,
		`https://codeload.github.com/${repo}/tar.gz/<validated-commit-sha>`,
	],
	caps,
	requiredRevisionWindow: { from: '2018-01-01T00:00:00Z', through: '2023-08-10T00:00:00Z' },
	publication: {
		evidenceRoot: `evidence/ingests/${slug}`,
		cacheRoot: relative(root, cacheRoot),
		transactional: true,
		readinessCredit: false,
	},
	nonclaims: [
		'Starting this transaction establishes no tag identity, license, source integrity, dependency closure, framework, build, browser behavior, migration feasibility, pilot status, or production readiness.',
		'The resulting evidence is reproducibility evidence, not certification or legal approval.',
	],
};
writeFileSync(join(evidenceDir, 'attempt.json'), `${JSON.stringify(attempt, null, 2)}\n`);

const source = {
	schemaVersion: 'versionless.official-source.v1',
	consentId,
	attemptSha256: sha256(readFileSync(join(evidenceDir, 'attempt.json'))),
	result: 'source-bound',
	startedAt,
	completedAt,
	repository: {
		id: repository.id,
		fullName: repository.full_name,
		private: repository.private,
		archived: repository.archived,
		disabled: repository.disabled,
		responseBytes: requests[0].bytes,
		responseSha256: requests[0].sha256,
	},
	revision: {
		ref: `refs/tags/${tag}`,
		tagObjectSha: tagObject?.sha ?? null,
		tagKind: tagObject ? 'annotated' : 'lightweight',
		tagDate: tagObject?.tagger?.date ?? null,
		tagVerification: tagObject?.verification?.verified ? 'verified' : 'unsigned',
		commitSha,
		commitDate: commit.committer?.date ?? null,
		commitVerification: commit.verification?.verified ? 'verified' : 'unsigned',
		rootTreeSha: commit.tree.sha,
		treeEntries: tree.tree.length,
		treeBlobs: tree.tree.filter((e) => e.type === 'blob').length,
		treeDirectories: tree.tree.filter((e) => e.type === 'tree').length,
		treeSymlinks: symlinks,
		treeGitlinks: gitlinks,
		treeTruncated: tree.truncated === true,
	},
	requests,
	archiveParity: {
		singleRoot,
		safeEntries: files.length + directories.length,
		regularFiles: files.length,
		directories: directories.length,
		specialEntries,
		gitBlobs: treeBlobs.size,
		missingFiles,
		extraFiles,
		mismatchedBlobs,
		normalizedManifestSha256,
	},
	transaction: {
		attemptedRequests: requests.length,
		acceptedResponses: requests.length,
		acceptedWireBytes: aggregate,
		acceptedDecodedBytes: aggregate,
		redirectsObserved,
		setCookiesUsed,
		retries: 0,
		archivesByteIdentical,
		archiveMatchesGitTree,
		publishedSource: true,
		readinessCredit: false,
		implementationStarted: false,
	},
	cache: {
		root: relative(root, cacheRoot),
		archive1: relative(root, archives[0].file),
		archive2: relative(root, archives[1].file),
		verifiedSource: relative(root, extractDir),
		rawMetadataPortable: false,
	},
	nonclaims: [
		'A lightweight or unsigned tag does not establish signer authenticity.',
		'No dependency closure, build, browser behavior, migration feasibility, pilot status, production readiness, certification, or legal approval is established by this record.',
	],
};
writeFileSync(join(evidenceDir, 'source.json'), `${JSON.stringify(source, null, 2)}\n`);
console.log(
	JSON.stringify(
		{
			result: 'source-bound',
			commitSha,
			archiveSha256: archives[0].sha256,
			archivesByteIdentical,
			archiveMatchesGitTree,
			files: files.length,
		},
		null,
		1,
	),
);
if (statSync(join(sourceRoot, 'assets/package.json')).size === 0) throw new Error('empty frontend');
lstatSync(sourceRoot);

