// T004 tranche-one admission probe (generic; repo + tag are arguments).
// Purpose-bound consent: VL-LEGACY-CORPUS-2026-08-10. Records every URL + byte digest.
import { createHash } from 'node:crypto';
import { appendFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { request } from 'node:https';

const dir = new URL('.', import.meta.url).pathname;
mkdirSync(dir, { recursive: true });
const sha256 = (b) => createHash('sha256').update(b).digest('hex');
const ledger = `${dir}probe-ledger.ndjson`;

export function get(url, kind = 'json') {
	return new Promise((resolve, reject) => {
		const call = request(
			url,
			{
				method: 'GET',
				headers: {
					accept:
						kind === 'json' ? 'application/vnd.github+json' : 'application/octet-stream',
					'accept-encoding': 'identity',
					'user-agent': 'versionless-shared-acquisition',
					'x-versionless-consent-id': process.env.VERSIONLESS_CONSENT_ID ?? '',
				},
			},
			(response) => {
				const chunks = [];
				response.on('data', (c) => chunks.push(c));
				response.once('end', () => {
					const body = Buffer.concat(chunks);
					appendFileSync(
						ledger,
						`${JSON.stringify({
							url,
							status: response.statusCode,
							bytes: body.byteLength,
							sha256: sha256(body),
						})}\n`,
					);
					resolve({ status: response.statusCode, body });
				});
				response.once('error', reject);
			},
		);
		call.once('error', reject);
		call.end();
	});
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
	const [repo, ref] = process.argv.slice(2);
	const api = `https://api.github.com/repos/${repo}`;
	const refResponse = await get(`${api}/git/ref/tags/${ref}`);
	const refJson = JSON.parse(refResponse.body.toString());
	let commitSha = refJson.object?.sha;
	let tag;
	if (refJson.object?.type === 'tag') {
		tag = JSON.parse((await get(`${api}/git/tags/${refJson.object.sha}`)).body.toString());
		commitSha = tag.object.sha;
	}
	const commit = JSON.parse((await get(`${api}/git/commits/${commitSha}`)).body.toString());
	const tree = JSON.parse(
		(await get(`${api}/git/trees/${commit.tree.sha}?recursive=1`)).body.toString(),
	);
	writeFileSync(`${dir}probe-tree.json`, JSON.stringify(tree));
	console.log(
		JSON.stringify(
			{
				repo,
				ref,
				tagObjectSha: tag?.sha ?? null,
				tagDate: tag?.tagger?.date ?? null,
				tagVerification: tag?.verification?.verified ? 'verified' : 'unsigned',
				commitSha,
				commitDate: commit.committer?.date ?? null,
				commitVerification: commit.verification?.verified ? 'verified' : 'unsigned',
				rootTreeSha: commit.tree.sha,
				truncated: tree.truncated,
				entries: tree.tree.length,
			},
			null,
			1,
		),
	);
	const interesting = tree.tree.filter((e) =>
		/(^|\/)(package\.json|LICENSE[^/]*|LICENCE[^/]*|webpack[^/]*|yarn\.lock|package-lock\.json)$/i.test(
			e.path,
		),
	);
	console.log(JSON.stringify(interesting.map((e) => [e.path, e.sha, e.size])));
}

