317	async function getExact(
318		artifact: Pick<SqlpadClosureArtifact, 'url' | 'integrity'>,
319		state: NetworkState,
320	): Promise<Buffer> {
321		assertSqlpadRegistryUrl(artifact.url);
322		for (let attempt = 1; attempt <= 3; attempt += 1) {
