324				return await new Promise((resolvePromise, reject) => {
325					let observedResponse = false;
326					const call = request(
327						artifact.url,
328						{
329							method: 'GET',
330							headers: {
331								accept: 'application/octet-stream',
332								'accept-encoding': 'identity',
333								'user-agent': 'versionless-t661',
334							},
335						},
336						(response) => {
337							observedResponse = true;
338							state.transportAttempts.push({
339								url: artifact.url,
340								attempt,
341								outcome: 'accepted',
342							});
343							if (
344								response.statusCode !== 200 ||
345								response.headers.location !== undefined ||
346								(response.headers['content-encoding'] ?? 'identity') !== 'identity'
347							) {
348								response.destroy();
349								reject(
350									new Error(
351										`SQLPad accepted response boundary differs: ${artifact.url}`,
352									),
353								);
354								return;
355							}
356							const chunks: Buffer[] = [];
357							let bytes = 0;
358							response.on('data', (chunk: Buffer) => {
359								bytes += chunk.byteLength;
360								if (
361									bytes > responseByteLimit ||
362									state.aggregateBytes + bytes > aggregateByteLimit
363								)
364									response.destroy(new Error('SQLPad acquisition byte cap exceeded'));
365								else chunks.push(Buffer.from(chunk));
366							});
367							response.once('error', reject);
368							response.once('end', () => {
369								const body = Buffer.concat(chunks, bytes);
370								if (!integrityMatches(body, artifact.integrity)) {
371									reject(
372										new Error(`SQLPad tarball integrity differs: ${artifact.url}`),
373									);
374									return;
375								}
376								state.acceptedResponses += 1;
377								state.aggregateBytes += bytes;
378								state.ledger.push({
379									url: artifact.url,
380									status: 200,
381									bytes,
382									sha256: sha256(body),
383									integrity: artifact.integrity,
384								});
385								resolvePromise(body);
386							});
387						},
388					);
389					call.setTimeout(requestTimeoutMilliseconds, () =>
390						call.destroy(new Error('SQLPad zero-response request timeout')),
391					);
392					call.once('error', (error) => {
393						if (!observedResponse) {
394							state.transportAttempts.push({
395								url: artifact.url,
396								attempt,
397								outcome: 'zero-response',
398							});
399							const wrapped = new Error(error.message);
400							Object.assign(wrapped, { zeroResponse: true });
401							reject(wrapped);
402						} else reject(error);
403					});
404					call.end();
405				});
406			} catch (error) {
407				if (!(error instanceof Error) || !('zeroResponse' in error) || attempt === 3)
408					throw error;
409			}
410		}
411		throw new Error('SQLPad transport attempts exhausted');
412	}
