414	function targetArtifacts(): SqlpadClosureArtifact[] {
415		return SQLPAD_TARGET_PACKAGES.map((artifact) => ({
416			name: artifact.name,
417			version: artifact.version,
418			url: artifact.url,
419			integrity: artifact.integrity,
