439					consentId: SQLPAD_CONSENT,
440					result: 'started',
441					artifacts: closure.artifacts.length,
442					placements: closure.placements,
443					caps: { responseLimit, responseByteLimit, aggregateByteLimit },
444				},
445				null,
446				2,
447			)}\n`,
448		);
449		await mkdir(join(cacheStage, 'mirror'), { recursive: true });
450		const transaction: NetworkState = {
451			acceptedResponses: 0,
452			aggregateBytes: 0,
453			transportAttempts: [],
454			ledger: [],
455		};
456		try {
457			for (const artifact of [...closure.artifacts, ...targets]) {
458				const bytes = await getExact(artifact, transaction);
459				artifact.sha256 = sha256(bytes);
460				artifact.bytes = bytes.byteLength;
461				await writeFile(join(cacheStage, 'mirror', artifact.mirror), bytes);
462			}
463			const unsigned = {
464				schemaVersion: 'versionless.react-sqlpad-v5-5-0-closure.v1' as const,
465				consentId: SQLPAD_CONSENT,
466				source: { revision: SQLPAD_REVISION, tree: SQLPAD_TREE },
467				artifacts: closure.artifacts,
468				targetArtifacts: targets,
469				transaction,
470				constraints: {
471					installScriptsExecuted: false as const,
472					localTechnicalEvaluationOnly: true as const,
473					legalReviewRequired: true as const,
474					redistributionAuthorized: false as const,
475				},
476			};
477			const receipt: SqlpadClosureReceipt = {
478				...unsigned,
479				integrity: { algorithm: 'sha256', canonicalDigest: sha256(canonicalize(unsigned)) },
480			};
481			await writeFile(join(cacheStage, 'closure.json'), `${canonicalize(receipt)}\n`);
482			await rename(cacheStage, cacheRoot);
483			await writeFile(receiptPath, `${canonicalize(receipt)}\n`);
484		} catch (error) {
485			await writeFile(
486				join(evidenceRoot, 'consumed-failed.json'),
487				`${canonicalize({
488					schemaVersion: 'versionless.react-sqlpad-v5-5-0-closure-failure.v1',
489					consentId: SQLPAD_CONSENT,
490					result: 'terminal-failure',
491					transaction,
492					error: error instanceof Error ? error.message : String(error),
493				})}\n`,
494			);
