496		}
497	}
498	
499	export async function verifySqlpadClosure(): Promise<{
500		valid: true;
501		artifacts: number;
502		digest: string;
503	}> {
504		const published = JSON.parse(await readFile(receiptPath, 'utf8')) as SqlpadClosureReceipt;
505		const cached = JSON.parse(
506			await readFile(join(cacheRoot, 'closure.json'), 'utf8'),
507		) as SqlpadClosureReceipt;
508		if (canonicalize(published) !== canonicalize(cached))
509			throw new Error('SQLPad closure publication differs');
510		const { integrity, ...unsigned } = published;
511		if (
512			published.schemaVersion !== 'versionless.react-sqlpad-v5-5-0-closure.v1' ||
513			published.consentId !== SQLPAD_CONSENT ||
514			published.source.revision !== SQLPAD_REVISION ||
515			published.source.tree !== SQLPAD_TREE ||
516			published.transaction.acceptedResponses !==
517				published.artifacts.length + published.targetArtifacts.length ||
518			integrity.canonicalDigest !== sha256(canonicalize(unsigned))
519		)
520			throw new Error('SQLPad closure receipt differs');
521		for (const artifact of [...published.artifacts, ...published.targetArtifacts]) {
522			const bytes = await readFile(join(cacheRoot, 'mirror', artifact.mirror));
523			if (
524				bytes.byteLength !== artifact.bytes ||
525				sha256(bytes) !== artifact.sha256 ||
526				!integrityMatches(bytes, artifact.integrity)
527			)
528				throw new Error(
529					`SQLPad offline artifact differs: ${artifact.name}@${artifact.version}`,
530				);
531		}
532		const mirrorEntries = (await readdir(join(cacheRoot, 'mirror'))).sort(compareText);
533		if (mirrorEntries.length !== published.artifacts.length + published.targetArtifacts.length)
534			throw new Error('SQLPad closure mirror cardinality differs');
535		return {
536			valid: true,
537			artifacts: published.artifacts.length + published.targetArtifacts.length,
538			digest: integrity.canonicalDigest,
539		};
540	}
541	
542	export async function main(args = process.argv.slice(2)): Promise<void> {
543		const mode = parseSqlpadIngestLauncher(args);
544		if (mode === 'acquire') await acquireSqlpadClosure();
545		if (mode !== 'launcher-smoke')
546			process.stdout.write(`${canonicalize(await verifySqlpadClosure())}\n`);
547	}
548	
549	if (basename(process.argv[1] ?? '') === 'react-sqlpad-v5-5-0-ingest.ts')
550		main().catch((error: unknown) => {
551			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
552			process.exitCode = 1;
553		});
